python3 - <<'PY'
import pathlib
p = pathlib.Path("src/codegen_support/runtime/exceptions/uncaught_report.rs")
s = p.read_text()
a = '''/// Byte length of the constant fallback message, kept in sync with `data::fixed`.
const UNCAUGHT_FALLBACK_LEN: i64 = 32;
'''
b = '''/// Byte length of the constant fallback message, kept in sync with `data::fixed`.
const UNCAUGHT_FALLBACK_LEN: i64 = 32;

/// Byte length of `"\\nNext "`, the introducer php puts before every link after the first.
const UNCAUGHT_NEXT_LEN: i64 = 6;

/// Offset of a compact Throwable's `previous` slot — see `sentinels`, which lays the payload out.
const THROWABLE_PREVIOUS_OFFSET: i64 = 40;
'''
assert s.count(a) == 1, s.count(a)
p.write_text(s.replace(a, b))
print("constants added")
